package store

// The exact normalized, comment-free text of every recipient (classVIS), shared-admin (classShared) and
// organization-key custody (classOperatorCustody) statement in queries/model_providers.sql, as
// statementsOf returns it (PRD #4540 R4, R5). A visibility predicate is a fragment of SQL, and a
// fragment rule cannot see a widening that keeps the fragment (an appended OR, an optional predicate,
// a dropped bind). Pinning the whole text makes any edit to these statements a reviewed edit of this
// file. The recipient texts are the text at the base of PRD #4540 M1, byte-for-byte: M1 does not
// touch a recipient reader. Do not regenerate a recipient entry to make a failing test pass.
var exactSQL = map[string]string{
	// recipient reads and the recipient write path (unchanged by PRD #4540)
	"GetProviderKeyForUpdate":                      `SELECT k.id, k.disabled_at, k.enablement_rev FROM user_secrets k JOIN model_providers p ON p.id = k.provider_id AND (p.owner_user_id = k.user_id OR (p.owner_user_id IS NULL AND p.credential_mode = 'per_user_key')) WHERE k.user_id = $1 AND k.provider_id = $2 AND k.kind = CASE p.engine WHEN 'claude' THEN 'anthropic_compatible_key' WHEN 'codex' THEN 'openai_compatible_key' END FOR UPDATE OF k;`,
	"InsertProviderKeySecret":                      `INSERT INTO user_secrets (user_id, kind, label, is_default, auto_eligible, ciphertext, sealed_with, provider_id, provider_scope_id) SELECT @user_id::uuid, CASE p.engine WHEN 'claude' THEN 'anthropic_compatible_key' WHEN 'codex' THEN 'openai_compatible_key' END, @label, false, false, @ciphertext, @sealed_with, @provider_id, p.scope_owner_id FROM model_providers p WHERE p.id = @provider_id AND (p.owner_user_id = @user_id::uuid OR (p.owner_user_id IS NULL AND p.credential_mode = 'per_user_key')) RETURNING id, kind, label, is_default, auto_eligible, created_at, updated_at;`,
	"GetUserProviderSource":                        `SELECT u.claude_provider_id AS provider_id, p.engine, r.protocol, p.current_revision, p.retired_at, r.base_url, r.auth_style, r.model_map, k.id AS key_secret_id, k.kind AS key_kind, k.provider_id AS key_provider_id, k.disabled_at AS key_disabled_at, k.enablement_rev AS key_enablement_rev FROM users u LEFT JOIN model_providers p ON p.id = u.claude_provider_id AND (p.owner_user_id = u.id OR (p.owner_user_id IS NULL AND p.credential_mode = 'per_user_key')) AND p.engine = @engine LEFT JOIN model_provider_revisions r ON r.provider_id = p.id AND r.revision = p.current_revision LEFT JOIN user_secrets k ON k.user_id = u.id AND k.provider_id = p.id AND k.kind = CASE p.engine WHEN 'claude' THEN 'anthropic_compatible_key' WHEN 'codex' THEN 'openai_compatible_key' END WHERE u.id = @id AND @engine::text = 'claude' UNION ALL SELECT u.codex_provider_id AS provider_id, p.engine, r.protocol, p.current_revision, p.retired_at, r.base_url, r.auth_style, r.model_map, k.id AS key_secret_id, k.kind AS key_kind, k.provider_id AS key_provider_id, k.disabled_at AS key_disabled_at, k.enablement_rev AS key_enablement_rev FROM users u LEFT JOIN model_providers p ON p.id = u.codex_provider_id AND (p.owner_user_id = u.id OR (p.owner_user_id IS NULL AND p.credential_mode = 'per_user_key')) AND p.engine = @engine LEFT JOIN model_provider_revisions r ON r.provider_id = p.id AND r.revision = p.current_revision LEFT JOIN user_secrets k ON k.user_id = u.id AND k.provider_id = p.id AND k.kind = CASE p.engine WHEN 'claude' THEN 'anthropic_compatible_key' WHEN 'codex' THEN 'openai_compatible_key' END WHERE u.id = @id AND @engine::text = 'codex';`,
	"SetUserProviderSource":                        `UPDATE users u SET claude_provider_id = CASE WHEN @engine::text = 'claude' THEN sqlc.narg('provider_id')::uuid ELSE claude_provider_id END, claude_provider_scope_id = CASE WHEN @engine::text = 'claude' THEN (SELECT sp.scope_owner_id FROM model_providers sp WHERE sp.id = sqlc.narg('provider_id')::uuid) ELSE claude_provider_scope_id END, codex_provider_id = CASE WHEN @engine::text = 'codex' THEN sqlc.narg('provider_id')::uuid ELSE codex_provider_id END, codex_provider_scope_id = CASE WHEN @engine::text = 'codex' THEN (SELECT sp.scope_owner_id FROM model_providers sp WHERE sp.id = sqlc.narg('provider_id')::uuid) ELSE codex_provider_scope_id END WHERE u.id = @id AND @engine::text IN ('claude', 'codex') AND (sqlc.narg('provider_id')::uuid IS NULL OR (@engine::text = 'claude' AND EXISTS ( SELECT 1 FROM model_providers p WHERE p.id = sqlc.narg('provider_id')::uuid AND (p.owner_user_id = u.id OR (p.owner_user_id IS NULL AND p.credential_mode = 'per_user_key')) AND p.engine = 'claude')) OR (@engine::text = 'codex' AND EXISTS ( SELECT 1 FROM model_providers p WHERE p.id = sqlc.narg('provider_id')::uuid AND (p.owner_user_id = u.id OR (p.owner_user_id IS NULL AND p.credential_mode = 'per_user_key')) AND p.engine = 'codex'))) RETURNING claude_provider_id, codex_provider_id;`,
	"LockModelProviderForShare":                    `SELECT p.id, p.current_revision, p.retired_at FROM model_providers p WHERE p.id = @id AND (p.owner_user_id = @owner_user_id::uuid OR (p.owner_user_id IS NULL AND p.credential_mode = 'per_user_key')) FOR SHARE OF p;`,
	"GetModelProviderRevisionForOwner":             `SELECT r.provider_id, r.revision, r.protocol, r.base_url, r.auth_style, r.model_map, p.engine FROM model_provider_revisions r JOIN model_providers p ON p.id = r.provider_id WHERE r.provider_id = @provider_id AND r.revision = @revision AND (p.owner_user_id = @owner_user_id::uuid OR (p.owner_user_id IS NULL AND p.credential_mode = 'per_user_key')) FOR KEY SHARE OF r;`,
	"LockProviderBindingRevisionForKeyShareNowait": `SELECT r.provider_id, r.revision, r.protocol, r.base_url, r.auth_style, r.model_map, p.engine FROM model_provider_revisions r JOIN model_providers p ON p.id = r.provider_id WHERE r.provider_id = @provider_id AND r.revision = @revision AND (p.owner_user_id = @owner_user_id::uuid OR (p.owner_user_id IS NULL AND p.credential_mode = 'per_user_key')) FOR KEY SHARE OF r NOWAIT;`,
	"ListRunProviderNames":                         `SELECT r.id AS run_id, p.name FROM runs r JOIN model_providers p ON p.id = r.model_provider_id AND (p.owner_user_id = r.user_id OR (p.owner_user_id IS NULL AND p.credential_mode = 'per_user_key')) WHERE r.id = ANY(@run_ids::uuid[]);`,
	"ListVisibleProviders":                         `SELECT p.id, p.name, p.engine, p.current_revision, p.retired_at, p.created_at, p.credential_mode, p.owner_user_id, r.protocol, r.base_url, r.auth_style, r.model_map, k.id AS key_secret_id, k.disabled_at AS key_disabled_at, k.enablement_rev AS key_enablement_rev, t.auth_result AS probe_auth_result, t.tool_result AS probe_tool_result, t.probed_at AS probed_at FROM model_providers p JOIN model_provider_revisions r ON r.provider_id = p.id AND r.revision = p.current_revision LEFT JOIN user_secrets k ON k.user_id = @user_id::uuid AND k.provider_id = p.id AND k.kind = CASE p.engine WHEN 'claude' THEN 'anthropic_compatible_key' WHEN 'codex' THEN 'openai_compatible_key' END LEFT JOIN model_provider_key_test_results t ON t.provider_id = p.id AND t.user_id = @user_id::uuid AND t.revision = p.current_revision AND t.key_secret_id = k.id AND t.key_enablement_rev = k.enablement_rev WHERE (p.owner_user_id = @user_id::uuid OR (p.owner_user_id IS NULL AND p.credential_mode = 'per_user_key')) ORDER BY lower(p.name), p.id;`,
	"GetVisibleProviderForUse":                     `SELECT p.id, p.name, p.engine, p.current_revision, p.retired_at, p.created_at, p.credential_mode, p.owner_user_id, r.protocol, r.base_url, r.auth_style, r.model_map, k.id AS key_secret_id, k.disabled_at AS key_disabled_at, k.enablement_rev AS key_enablement_rev, t.auth_result AS probe_auth_result, t.tool_result AS probe_tool_result, t.probed_at AS probed_at FROM model_providers p JOIN model_provider_revisions r ON r.provider_id = p.id AND r.revision = p.current_revision LEFT JOIN user_secrets k ON k.user_id = @user_id::uuid AND k.provider_id = p.id AND k.kind = CASE p.engine WHEN 'claude' THEN 'anthropic_compatible_key' WHEN 'codex' THEN 'openai_compatible_key' END LEFT JOIN model_provider_key_test_results t ON t.provider_id = p.id AND t.user_id = @user_id::uuid AND t.revision = p.current_revision AND t.key_secret_id = k.id AND t.key_enablement_rev = k.enablement_rev WHERE p.id = @id AND (p.owner_user_id = @user_id::uuid OR (p.owner_user_id IS NULL AND p.credential_mode = 'per_user_key'));`,
	"LockVisibleProviderForKeyMutation":            `SELECT p.id, p.engine, p.current_revision, p.retired_at, p.credential_mode, p.owner_user_id FROM model_providers p WHERE p.id = @id AND (p.owner_user_id = @user_id::uuid OR (p.owner_user_id IS NULL AND p.credential_mode = 'per_user_key')) FOR KEY SHARE OF p;`,
	"LockVisibleProviderForEvidence":               `SELECT p.id, p.engine, p.current_revision FROM model_providers p WHERE p.id = @id AND (p.owner_user_id = @user_id::uuid OR (p.owner_user_id IS NULL AND p.credential_mode = 'per_user_key')) AND p.current_revision = @revision AND p.retired_at IS NULL FOR SHARE OF p;`,
	// shared-admin (both credential modes)
	"LockSharedModelProviderCatalogue":  `SELECT pg_advisory_xact_lock( 1970957680, hashtext('00000000-0000-0000-0000-000000000000') );`,
	"CountSharedModelProviders":         `SELECT count(*) FROM model_providers WHERE owner_user_id IS NULL AND credential_mode IN ('per_user_key', 'operator_key');`,
	"InsertSharedModelProvider":         `INSERT INTO model_providers (owner_user_id, name, engine, current_revision, credential_mode, scope_owner_id) VALUES (NULL, @name, @engine, 1, 'per_user_key', '00000000-0000-0000-0000-000000000000'::uuid) RETURNING id, owner_user_id, name, engine, current_revision, retired_at, created_at, credential_mode, scope_owner_id;`,
	"InsertSharedOperatorModelProvider": `INSERT INTO model_providers (owner_user_id, name, engine, current_revision, credential_mode, scope_owner_id) VALUES (NULL, @name, 'claude', 1, 'operator_key', '00000000-0000-0000-0000-000000000000'::uuid) RETURNING id, owner_user_id, name, engine, current_revision, retired_at, created_at, credential_mode, scope_owner_id;`,
	"LockSharedModelProviderForEdit":    `SELECT p.id, p.name, p.engine, p.current_revision, p.retired_at, p.credential_mode FROM model_providers p WHERE p.id = @id AND p.owner_user_id IS NULL AND p.credential_mode IN ('per_user_key', 'operator_key') FOR NO KEY UPDATE OF p;`,
	"BumpSharedModelProviderRevision":   `UPDATE model_providers SET current_revision = current_revision + 1 WHERE id = @id AND owner_user_id IS NULL AND credential_mode IN ('per_user_key', 'operator_key') AND retired_at IS NULL RETURNING current_revision;`,
	"RenameSharedModelProvider":         `UPDATE model_providers SET name = @name WHERE id = @id AND owner_user_id IS NULL AND credential_mode IN ('per_user_key', 'operator_key');`,
	"RetireSharedModelProvider":         `UPDATE model_providers SET retired_at = COALESCE(retired_at, now()) WHERE id = @id AND owner_user_id IS NULL AND credential_mode IN ('per_user_key', 'operator_key');`,
	"PruneSharedModelProviderRevisions": `DELETE FROM model_provider_revisions rev USING model_providers p WHERE rev.provider_id = @id AND p.id = rev.provider_id AND p.owner_user_id IS NULL AND p.credential_mode IN ('per_user_key', 'operator_key') AND rev.revision <> p.current_revision AND NOT EXISTS ( SELECT 1 FROM runs r WHERE r.model_provider_id = rev.provider_id AND r.model_provider_revision = rev.revision);`,
	"LockSharedModelProviderForDelete":  `SELECT p.id, p.name, p.current_revision, p.retired_at FROM model_providers p WHERE p.id = @id AND p.owner_user_id IS NULL AND p.credential_mode IN ('per_user_key', 'operator_key') FOR UPDATE OF p;`,
	"DeleteSharedModelProvider":         `DELETE FROM model_providers WHERE id = @id AND owner_user_id IS NULL AND credential_mode IN ('per_user_key', 'operator_key');`,
	"DeleteSharedProviderKeys":          `DELETE FROM user_secrets WHERE provider_id = @id::uuid AND provider_scope_id = '00000000-0000-0000-0000-000000000000'::uuid RETURNING id;`,
	"CountSharedProviderSelections":     `SELECT count(*) FROM users WHERE (claude_provider_id = @id::uuid AND claude_provider_scope_id = '00000000-0000-0000-0000-000000000000'::uuid) OR (codex_provider_id = @id::uuid AND codex_provider_scope_id = '00000000-0000-0000-0000-000000000000'::uuid);`,
	"ListSharedModelProvidersAdmin":     `SELECT p.id, p.name, p.engine, p.current_revision, p.retired_at, p.created_at, p.credential_mode, r.protocol, r.base_url, r.auth_style, r.model_map, COALESCE(su.n, 0)::bigint AS selected_user_count, COALESCE(ak.n, 0)::bigint AS attached_key_count, (cust.provider_id IS NOT NULL)::boolean AS operator_key_present, cust.disabled_at AS operator_key_disabled_at, cust.set_at AS operator_key_set_at, cev.auth_result, cev.tool_result, cev.probed_at FROM model_providers p JOIN model_provider_revisions r ON r.provider_id = p.id AND r.revision = p.current_revision LEFT JOIN model_provider_operator_keys cust ON cust.provider_id = p.id LEFT JOIN model_provider_operator_key_test_results cev ON cev.provider_id = p.id AND cev.revision = p.current_revision AND cev.key_id = cust.id AND cev.key_rev = cust.key_rev AND p.retired_at IS NULL LEFT JOIN (SELECT sel.pid, count(*) AS n FROM ( SELECT id AS uid, claude_provider_id AS pid FROM users WHERE claude_provider_scope_id = '00000000-0000-0000-0000-000000000000'::uuid UNION SELECT id AS uid, codex_provider_id AS pid FROM users WHERE codex_provider_scope_id = '00000000-0000-0000-0000-000000000000'::uuid) sel GROUP BY sel.pid) su ON su.pid = p.id LEFT JOIN (SELECT provider_id AS pid, count(*) AS n FROM user_secrets WHERE provider_scope_id = '00000000-0000-0000-0000-000000000000'::uuid GROUP BY provider_id) ak ON ak.pid = p.id WHERE p.owner_user_id IS NULL AND p.credential_mode IN ('per_user_key', 'operator_key') ORDER BY lower(p.name), p.id;`,
	"GetSharedModelProviderAdmin":       `SELECT p.id, p.name, p.engine, p.current_revision, p.retired_at, p.created_at, p.credential_mode, r.protocol, r.base_url, r.auth_style, r.model_map, COALESCE(su.n, 0)::bigint AS selected_user_count, COALESCE(ak.n, 0)::bigint AS attached_key_count, (cust.provider_id IS NOT NULL)::boolean AS operator_key_present, cust.disabled_at AS operator_key_disabled_at, cust.set_at AS operator_key_set_at, cev.auth_result, cev.tool_result, cev.probed_at FROM model_providers p JOIN model_provider_revisions r ON r.provider_id = p.id AND r.revision = p.current_revision LEFT JOIN model_provider_operator_keys cust ON cust.provider_id = p.id LEFT JOIN model_provider_operator_key_test_results cev ON cev.provider_id = p.id AND cev.revision = p.current_revision AND cev.key_id = cust.id AND cev.key_rev = cust.key_rev AND p.retired_at IS NULL LEFT JOIN (SELECT sel.pid, count(*) AS n FROM ( SELECT id AS uid, claude_provider_id AS pid FROM users WHERE claude_provider_scope_id = '00000000-0000-0000-0000-000000000000'::uuid UNION SELECT id AS uid, codex_provider_id AS pid FROM users WHERE codex_provider_scope_id = '00000000-0000-0000-0000-000000000000'::uuid) sel GROUP BY sel.pid) su ON su.pid = p.id LEFT JOIN (SELECT provider_id AS pid, count(*) AS n FROM user_secrets WHERE provider_scope_id = '00000000-0000-0000-0000-000000000000'::uuid GROUP BY provider_id) ak ON ak.pid = p.id WHERE p.id = @id AND p.owner_user_id IS NULL AND p.credential_mode IN ('per_user_key', 'operator_key');`,
	// organization key custody and the admin Test evidence
	"LockOperatorProviderKeyForWrite":     `SELECT id, key_rev, disabled_at FROM model_provider_operator_keys WHERE provider_id = @provider_id FOR UPDATE;`,
	"InsertOperatorProviderKey":           `INSERT INTO model_provider_operator_keys (provider_id, ciphertext, set_by) VALUES (@provider_id, @ciphertext, @set_by) RETURNING id, key_rev, disabled_at, set_at;`,
	"ReplaceOperatorProviderKey":          `UPDATE model_provider_operator_keys SET ciphertext = @ciphertext, key_rev = nextval('model_provider_operator_key_rev_seq'), set_by = @set_by, set_at = now() WHERE provider_id = @provider_id RETURNING id, key_rev, disabled_at, set_at;`,
	"DisableOperatorProviderKey":          `UPDATE model_provider_operator_keys SET disabled_at = now(), key_rev = nextval('model_provider_operator_key_rev_seq') WHERE provider_id = @provider_id AND disabled_at IS NULL;`,
	"EnableOperatorProviderKey":           `UPDATE model_provider_operator_keys SET disabled_at = NULL, key_rev = nextval('model_provider_operator_key_rev_seq') WHERE provider_id = @provider_id AND disabled_at IS NOT NULL;`,
	"DeleteOperatorProviderKey":           `DELETE FROM model_provider_operator_keys WHERE provider_id = @provider_id;`,
	"GetOperatorProviderKeyForTest":       `SELECT ciphertext, key_rev FROM model_provider_operator_keys WHERE id = @id AND provider_id = @provider_id AND key_rev = @key_rev AND disabled_at IS NULL;`,
	"GetOperatorProviderForTest":          `SELECT p.id, p.name, p.current_revision, p.retired_at, r.protocol, r.base_url, r.auth_style, r.model_map, cust.id AS key_id, cust.key_rev AS key_rev, cust.disabled_at AS key_disabled_at FROM model_providers p JOIN model_provider_revisions r ON r.provider_id = p.id AND r.revision = p.current_revision LEFT JOIN model_provider_operator_keys cust ON cust.provider_id = p.id WHERE p.id = @id AND p.owner_user_id IS NULL AND p.credential_mode = 'operator_key';`,
	"LockOperatorProviderForEvidence":     `SELECT p.id, p.current_revision FROM model_providers p WHERE p.id = @id AND p.owner_user_id IS NULL AND p.credential_mode = 'operator_key' AND p.current_revision = @revision AND p.retired_at IS NULL FOR SHARE OF p;`,
	"LockOperatorProviderKeyForEvidence":  `SELECT k.id, k.key_rev FROM model_provider_operator_keys k WHERE k.id = @key_id AND k.provider_id = @provider_id AND k.key_rev = @key_rev AND k.disabled_at IS NULL FOR SHARE;`,
	"UpsertOperatorProviderKeyTestResult": `INSERT INTO model_provider_operator_key_test_results (provider_id, revision, key_id, key_rev, auth_result, tool_result, probed_at, probed_by) VALUES (@provider_id, @revision, @key_id, @key_rev, @auth_result, @tool_result, now(), @probed_by) ON CONFLICT (provider_id) DO UPDATE SET revision = EXCLUDED.revision, key_id = EXCLUDED.key_id, key_rev = EXCLUDED.key_rev, auth_result = EXCLUDED.auth_result, tool_result = EXCLUDED.tool_result, probed_at = EXCLUDED.probed_at, probed_by = EXCLUDED.probed_by;`,
}
